  ("Assessment Validity: Face Validity", "When an assessment appears, on superficial inspection by non-experts, to measure what it claims to measure, it has:", "Face Validity (superficial appearance of test relevance).", ["Construct Validity.", "Criterion-Related Validity.", "Predictive Validity."]),
  ("Assessment Validity: Criterion-Related (Predictive Validity)", "A university uses an entrance examination score to accurately forecast an applicant's future Grade Point Average (GPA) during their first year of college. This demonstrates high:", "Predictive Criterion-Related Validity.", ["Concurrent Validity.", "Content Validity.", "Face Validity."]),
  ("Assessment Validity: Concurrent Validity", "When scores on a newly developed short diagnostic math test correlate highly with scores on an established, comprehensive standardized math achievement test administered at the same time, it establishes:", "Concurrent Criterion-Related Validity.", ["Predictive Validity.", "Content Validity.", "Face Validity."]),
  ("Assessment Validity: Construct Validity", "When an assessment measures an unobservable, theoretical psychological trait or psychological construct (such as 'Self-Efficacy', 'Critical Thinking', or 'Mathematical Anxiety'), it demonstrates:", "Construct Validity (evidence through convergent/divergent correlations and factor analysis).", ["Content Validity.", "Face Validity.", "Administrative Validity."]),
