  ("Relationship between Validity and Reliability", "Which of the following statements accurately characterizes the fundamental psychometric relationship between Validity and Reliability?", "'A test can be reliable without being valid, but a test CANNOT be valid without first being reliable.'", ["'A test can be valid without being reliable.'", "'Reliability and validity are identical concepts.'", "'A test that is valid is guaranteed to be 100% unreliable.'"]),
  ("Reliability Methods: Test-Retest Method (Stability)", "Administering the identical test to the same group of students on two separate occasions with a two-week interval measures:", "Test-Retest Reliability (Coefficient of Stability across time).", ["Equivalent Forms Reliability (Equivalence).", "Split-Half Reliability (Internal Consistency).", "Inter-Rater Reliability."]),
  ("Reliability Methods: Parallel / Equivalent Forms (Equivalence)", "Administering two different but equivalent forms (Form A and Form B) of a test covering identical content specifications to the same group of students measures:", "Equivalent Forms Reliability (Coefficient of Equivalence).", ["Test-Retest Reliability.", "Split-Half Reliability.", "Inter-Rater Reliability."]),
  ("Reliability Methods: Split-Half Method (Internal Consistency)", "Dividing a single test administration into two halves (e.g., Odd items vs Even items) and correlating the scores, then adjusting with the Spearman-Brown Prophecy Formula, measures:", "Split-Half Reliability (Internal Consistency).", ["Test-Retest Stability.", "Inter-Rater Agreement.", "Predictive Validity."])
