questions = []
for idx, item in enumerate(d):
    exp = item[4] if len(item) > 4 else f"This item evaluates assessment competence in {item[0]}. {item[2]} represents standard psychometric measurement, evaluation theory, and DepEd Order 8, s. 2015."
    questions.append(q(idx + 1, item[0], item[1], item[2], item[3], exp))

save('assessmentExams.ts', 'ASSESSMENT_EXAM_QUESTIONS', questions)
